    const ny = 24 + (i%3)*85 + Math.cos(t*0.35+i*0.9)*8;
    const nd = Math.sqrt((x-nx)**2 + (y-ny)**2);
    if(nd < 10) nodes += Math.pow((10-nd)/10, 1.5);
